import type { Metadata } from "next";
import type { Locale } from "./i18n/config";
import { localeTags } from "./i18n/config";
import type { RouteKey } from "./i18n/routes";

/**
 * Share previews (Open Graph) per page type: 1200 × 630 cards with the page's hero photo and headline, generated by
 * scripts/build-og.mjs into public/og/<locale>/<key>.jpg. Club, event and article pages share their own photo instead.
 * Pages without a card of their own (legal, sitemap …) inherit the home card from the layout.
 */
export const ogCards: Partial<Record<RouteKey, { image: string }>> & { home: { image: string } } = {
  home: { image: "/images/hero/home-1.jpg" },
  locations: { image: "/images/standorte/hero.jpg" },
  events: { image: "/images/events/hero.jpg" },
  academy: { image: "/images/academy/hero.jpg" },
  app: { image: "/images/hero/app.jpg" },
  magazine: { image: "/images/hero/courts.jpg" },
  franchise: { image: "/images/franchise/hero.jpg" },
  investors: { image: "/images/investoren/hero.jpg" },
  partners: { image: "/images/partner/hero.jpg" },
  about: { image: "/images/about/hero.jpg" },
  jobs: { image: "/images/jobs/hero.jpg" },
  faq: { image: "/images/hero/community.jpg" },
  company: { image: "/images/hero/community.jpg" },
};

/** openGraph for a page with its own card – the page's openGraph replaces the layout's, so type/locale/siteName repeat. */
export function ogFor(locale: Locale, key: keyof typeof ogCards): Metadata["openGraph"] {
  return {
    type: "website",
    siteName: "PadelCity",
    locale: localeTags[locale].og,
    images: [{ url: `/og/${locale}/${key}.jpg`, width: 1200, height: 630 }],
  };
}
